<!DOCTYPE html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0d0f"><title>Управление платформой — ARENA X</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root{color-scheme:dark;--bg:#0b0d0f;--surface:#121619;--surface2:#171c20;--line:#293136;--text:#f1f3f3;--muted:#929da3;--accent:#c9f15b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px/1.55 Manrope,Arial,sans-serif}a{color:inherit;text-decoration:none}.app{min-height:100vh;display:grid;grid-template-columns:238px 1fr}.sidebar{position:sticky;top:0;height:100vh;background:#0e1113;border-right:1px solid var(--line);padding:25px 17px;display:flex;flex-direction:column}.brand{font-size:17px;font-weight:800;letter-spacing:.14em;padding:0 10px 25px;border-bottom:1px solid var(--line)}.brand em{font-style:normal;color:var(--accent)}.brand-mark{display:inline-grid;place-items:center;width:25px;height:25px;border:1px solid var(--accent);color:var(--accent);font-size:9px;transform:rotate(45deg);border-radius:4px;margin-right:10px}.brand-mark span{transform:rotate(-45deg)}.side-label{font-size:9px;color:#657178;letter-spacing:.16em;font-weight:800;margin:25px 10px 9px}.side-link{display:flex;align-items:center;gap:11px;padding:11px 10px;margin:2px 0;color:#aab4b9;border:1px solid transparent;border-radius:4px;font-size:11px;transition:background .2s,color .2s,border-color .2s}.side-link:hover,.side-link.active{background:#1b2223;color:var(--accent);border-color:#313c2b}.side-icon{width:17px;color:var(--accent);text-align:center;font-size:14px}.side-bottom{margin-top:auto;border-top:1px solid var(--line);padding-top:14px}.main{min-width:0;padding:0 34px 45px}.topbar{height:70px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);color:var(--muted);font-size:11px}.top-actions{display:flex;align-items:center;gap:12px}.avatar{width:29px;height:29px;display:grid;place-items:center;background:#273023;border:1px solid #4a5b35;color:var(--accent);font-weight:800;border-radius:50%}.logout{background:transparent;border:1px solid #394247;color:var(--text);padding:8px 12px;border-radius:4px;cursor:pointer;font:inherit}.content{max-width:1280px;margin:0 auto}.heading{padding:34px 0 20px}.eyebrow{color:var(--accent);font-size:9px;font-weight:800;letter-spacing:.19em}.heading h1{font-size:32px;letter-spacing:-.055em;margin:8px 0 4px}.heading p{color:var(--muted);margin:0}.notice{padding:11px 13px;border:1px solid #40512c;background:#1a2115;color:#d8eea6;margin:10px 0 16px;font-size:11px}.error{padding:11px 13px;border:1px solid #713b3b;background:#241719;color:#ffaaaa;margin:10px 0 16px;font-size:11px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:13px 0 24px}.stat{background:var(--surface);border:1px solid var(--line);padding:17px 16px;min-width:0}.stat small{display:block;color:var(--muted);font-size:9px;letter-spacing:.08em}.stat strong{display:block;font-size:27px;letter-spacing:-.05em;margin-top:7px}.stat span{display:block;color:var(--accent);font-size:9px;margin-top:2px}.columns{display:grid;grid-template-columns:1.35fr .85fr;gap:13px;align-items:start}.panel{background:var(--surface);border:1px solid var(--line);margin-bottom:13px;min-width:0}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px 17px;border-bottom:1px solid var(--line)}.panel-head h2{font-size:13px;margin:0}.panel-head span{color:var(--muted);font-size:10px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;text-align:left}th{font-size:9px;color:#768188;letter-spacing:.09em;font-weight:700;padding:11px 14px;border-bottom:1px solid var(--line)}td{padding:12px 14px;border-bottom:1px solid #222a2e;font-size:10px}tbody tr:last-child td{border-bottom:0}tbody tr:hover{background:#ffffff04}.user-name{font-size:11px;font-weight:800}.sub{display:block;color:var(--muted);font-size:9px;margin-top:2px}.role-form{display:flex;gap:6px;align-items:center}.role-form select{background:#0b0d0f;color:var(--text);border:1px solid #354047;padding:7px 8px;font:inherit;border-radius:3px}.save{background:var(--accent);color:#111609;border:0;padding:8px 10px;border-radius:3px;font-size:9px;font-weight:800;cursor:pointer}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 16px;border-bottom:1px solid #222a2e}.row:last-child{border-bottom:0}.row strong{font-size:11px}.row small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.actions{display:flex;gap:6px}.action{padding:7px 9px;border:1px solid #3b464b;background:transparent;color:var(--text);font-size:9px;border-radius:3px;cursor:pointer}.action.accept{background:var(--accent);border-color:var(--accent);color:#111609;font-weight:800}.status{color:var(--accent);font-size:9px;font-weight:800;text-transform:uppercase}.empty{padding:20px;color:var(--muted);font-size:11px}.tournament-line{display:flex;justify-content:space-between;gap:12px;padding:13px 16px;border-bottom:1px solid #222a2e}.tournament-line:last-child{border:0}.tournament-line strong{font-size:11px}.tournament-line small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.quick{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:13px}.quick a{padding:12px;border:1px solid var(--line);color:#dce2e3;font-size:10px;transition:border-color .2s}.quick a:hover{border-color:var(--accent)}.quick b{display:block;color:var(--accent);font-size:9px;margin-bottom:5px;letter-spacing:.1em}
@media(max-width:1100px){.stats{grid-template-columns:repeat(3,1fr)}.columns{grid-template-columns:1fr}}@media(max-width:700px){.app{display:block}.sidebar{position:relative;height:auto;padding:15px 16px;border-right:0;border-bottom:1px solid var(--line)}.brand{padding:0 0 13px;border:0}.side-label,.side-bottom{display:none}.sidebar nav{display:flex;gap:5px;overflow-x:auto;padding-top:7px}.side-link{white-space:nowrap;padding:8px 10px}.main{padding:0 16px 30px}.topbar{height:54px}.heading{padding:25px 0 15px}.heading h1{font-size:27px}.stats{grid-template-columns:repeat(2,1fr)}.stat:last-child{grid-column:1/-1}.stat strong{font-size:23px}.columns{display:block}.panel-head{padding:13px}.row{align-items:flex-start;flex-direction:column}.actions{width:100%}.actions form{flex:1}.actions button{width:100%}.role-form{min-width:190px}.top-actions>span{display:none}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition-duration:.01ms!important}}
